// ── Journal: the paper trades kept in Supabase ──
function loadJournal(force) { const M = S.md; if (M.jbusy || (M.j && !force && Date.now() - M.jat < 120000)) return; M.jbusy = true; api("/api/journal").then((j) => { M.j = j; }).catch((e) => { M.j = { ready: false, why: e.message || "The journal could not be read." }; }).finally(() => { M.jbusy = false; M.jat = Date.now(); paint(); }); }
function journal(d) {
  const M = S.md, j = M.j; loadJournal();
  if (!j) return `<div class="card"><div class="note">Reading the journal…</div></div>`;
  if (!j.ready) return `<div class="md-ban a"><span class="chip a">Not set up</span><div><b>${esc(j.why || "The journal is not ready.")}</b><small>${esc(j.setup || "")} The steps are in UPLOAD_STEPS.txt of stage 29 (step 1 and step 3).</small></div></div>`;
  const st = j.stats, k4 = (l, x, extra = "") => `<div class="md-k"><small>${l}</small><b class="${col(x.avg)}">${x.n ? sg(x.avg, 2) : "—"}</b><span>${x.n ? `${x.n} closed · ${num(x.won, 0)}% won${extra}` : "no closed trade yet"}</span></div>`;
  const NEED = 60, bk = d.books || {}, ut = (B) => (B && B.record ? (B.record.unseen || B.record.all || {}).trades : null);
  const books = [["Swing longs", st.long, ut(bk.long) && ut(bk.long).mean, "g"], ["Swing shorts", st.short, ut(bk.short) && ut(bk.short).mean, "r"], ["Intraday shorts", st.day, d.day && d.day.trades && d.day.trades.unseen ? d.day.trades.unseen.avg : null, "b"], ["Intraday longs · not approved", st.dayl, d.day_long && d.day_long.trades && d.day_long.trades.unseen ? d.day_long.trades.unseen.avg : null, "b"]].filter((b) => b[1]);
  const verdict = (x, bt) => { if (!x || !x.n) return ["a", "collecting", `${NEED} sessions to go`]; const se = x.sd && x.n > 1 ? x.sd / Math.sqrt(x.n) : null, z = se && ok(bt) ? (x.avg - bt) / se : null, left = Math.max(0, NEED - (x.sessions || 0));
    if (left > 0) return ["a", "collecting", `${left} session${left === 1 ? "" : "s"} to go${z != null ? (z <= -2 ? " · well below the backtest so far" : x.avg > 0 ? " · in line so far" : " · losing so far") : ""}`];
    if (x.avg <= 0) return ["r", "failed", "losing after costs"]; if (z != null && z <= -2) return ["r", "failed", "well below the backtest"];
    return z != null && z > -1 ? ["g", "passed", "in line with the backtest"] : ["a", "unclear", "positive but below the backtest"]; };
  const AU = j.audit || null, KY = { "Swing longs": "long", "Swing shorts": "short", "Intraday shorts": "day", "Intraday longs · not approved": "dayl" }, VC = { pass: ["g", "passed"], fail: ["r", "failed"], warn: ["a", "warning"], collecting: ["a", "collecting"], "no benchmark": ["", "no benchmark"] };
  const chk = (nm, x, bt) => { const a = AU && AU[KY[nm]]; if (!a) { const v = verdict(x, bt); return { v, sess: x.sessions || 0, paper: x.n ? x.avg : null, bt, z: null }; }      // a worker from before stage 37: the old trade-level guess
    const extra = [a.cone ? `${a.cone_n}-session cone ${sg(a.cone[0], 2)} / ${sg(a.cone[1], 2)}` : "", ok(a.wz) ? `win rate ${num(a.win, 0)}% against ${num(a.bt_win, 0)}%` : "", ok(a.slip) ? `your slippage ${sg(a.slip, 3)} (${a.fills} fills, ${a.slip_v})` : ""].filter(Boolean).join(" · ");
    return { v: [...(VC[a.verdict] || ["", a.verdict]), a.why + (extra ? " · " + extra : "")], sess: a.n, paper: a.mean, bt: a.bt, z: a.z }; };
  const fwdRows = books.map(([nm, x, bt, c]) => { const k = chk(nm, x, bt), v = k.v; return `<tr><td><span class="chip ${c}">${esc(nm)}</span></td><td class="r">${num(Math.min(k.sess || 0, 999), 0)} of ${NEED}</td><td class="r">${num(x.n || 0, 0)}</td><td class="r ${col(k.paper)}">${ok(k.paper) ? sg(k.paper, 2) : "—"}</td><td class="r ${col(k.bt)}">${sg(k.bt, 2)}</td><td class="r">${ok(k.z) ? (k.z >= 0 ? "+" : "−") + num(Math.abs(k.z), 1) : "—"}</td><td><span class="chip ${v[0]}">${v[1]}</span><small>${esc(v[2])}</small></td></tr>`; });
  const fwdCards = books.map(([nm, x, bt, c]) => { const k = chk(nm, x, bt), v = k.v; return `<div><span><b>${esc(nm)}</b><small>${num(k.sess || 0, 0)} of ${NEED} sessions · ${num(x.n || 0, 0)} closed · paper ${ok(k.paper) ? sg(k.paper, 2) : "—"} · backtest ${sg(k.bt, 2)}${ok(k.z) ? ` · z ${k.z >= 0 ? "+" : "−"}${num(Math.abs(k.z), 1)}` : ""}</small><small>${esc(v[2])}</small></span><span class="chip ${v[0]}">${v[1]}</span></div>`; }).join("");
  const HY = j.hyp ? [["H1 · pre-open queue at about 9:07", j.hyp.h1], ["H2 · order book at the first check after 9:30", j.hyp.h2]].filter((x) => x[1]) : [];
  const hyp = HY.length ? h("Two ideas written down before their data existed", "judged once, after 120 sessions; nothing changes before that") + `<div class="md-vl">${HY.map(([nm, x]) => `<div><span><b>${esc(nm)}</b><small>${x.verdict === "collecting" ? `${num(x.sessions, 0)} of ${x.need} sessions collected` : `${num(x.sessions, 0)} sessions · spread ${sg(x.spread, 3)} · t ${num(x.t, 2)}`} · predicted: buy-heavy books make the short worse (a ${x.predicted} spread)</small></span><span class="chip ${x.verdict === "holds" ? "g" : x.verdict === "fails" ? "r" : "a"}">${esc(x.verdict)}</span></div>`).join("")}</div><div class="note">Within each session the intraday shorts are split into thirds by the reading; the spread is the top third's result minus the bottom third's, after costs. An idea holds only with the predicted sign, t of 2 or more, and the same sign in both halves of the sessions. Angel One's pre-open numbers have not been checked against the exchange's yet: if they turn out not to move in the pre-open, H1 will say so and be dropped.</div>` : "";
  const rows = j.rows.map((r) => { const dy = r.kind === "day", res = r.status === "closed" ? r.net_pct : r.last_price > 0 ? (r.side === "long" ? 1 : -1) * (r.last_price / r.entry - 1) * 100 : null;
    return `<tr><td>${nice(r.trade_date).replace(/ \d{4}$/, "")}</td><td><b>${esc(r.symbol)}</b> <span class="chip ${dy ? "b" : r.side === "long" ? "g" : "r"}">${dy ? (r.side === "long" ? "Intraday long" : "Intraday short") : r.side === "long" ? "Swing long" : "Swing short"}</span></td><td class="r ${col(res)}"><b>${sg(res, 2)}</b>${dy && r.net_live_pct != null ? `<small>${sg(r.net_live_pct, 2)} from live</small>` : ""}</td><td><span class="chip ${r.status === "open" ? "a" : r.exit_reason === "stop" ? "r" : r.exit_reason === "target" ? "g" : ""}">${r.status === "open" ? `open · day ${r.days}${r.hold > 1 ? " of " + r.hold : ""}` : esc(r.exit_reason === "rank" ? "rank fell" : r.exit_reason || "closed")}</span></td><td class="r">${px(r.entry)}${dy && r.entry_live > 0 ? `<small>live ${px(r.entry_live)}</small>` : ""}</td><td class="r dn">${px(r.stop)}</td><td class="r up">${r.target != null ? px(r.target) : dy ? "3:05 pm" : "top " + (KEEP(d) ? KEEP(d).keep_rank : "—")}</td><td class="r">${r.status === "closed" ? px(r.exit_price) : px(r.last_price)}</td>${isDesk() ? `<td class="r">${r.fill_price > 0 ? `${px(r.fill_price)}<small class="${col(-(r.side === "short" ? 1 - r.fill_price / r.entry : r.fill_price / r.entry - 1))}">${sg((r.side === "short" ? 1 - r.fill_price / r.entry : r.fill_price / r.entry - 1) * 100, 2)} slip</small>` : "—"}</td>` : ""}</tr>`; });
  return `<div class="md-lh"><div><b>Paper journal</b><small>Every model trade, opened and closed by the site on Angel One prices and kept in Supabase. No real order is ever placed.</small></div><div><small>Last snapshot of the F&O list</small><b>${j.snaps && j.snaps.last ? new Date(j.snaps.last).toLocaleString("en-IN", { day: "numeric", month: "short", hour: "2-digit", minute: "2-digit" }) : "none yet"}</b></div></div>
    <div class="md-kg">${k4("Swing longs, average trade", st.long)}${k4("Swing shorts, average trade", st.short)}${k4("Intraday shorts, from the official open", st.day)}<div class="md-k"><small>Intraday shorts, from the live price</small><b class="${col(st.day.live)}">${ok(st.day.live) ? sg(st.day.live, 2) : "—"}</b><span>${ok(st.day.slip) ? `the live price was ${num(Math.abs(st.day.slip), 2)}% ${st.day.slip >= 0 ? "worse" : "better"} than the open` : "shows what the open really costs"}</span></div>${st.dayl ? k4("Intraday longs, paper only", st.dayl, " · not approved") : ""}</div>
    ${h("Before real money · 60 sessions for each book", "paper sessions against the 2025–26 backtest, after costs")}<div class="only-d">${tbl([["Book"], ["Sessions", 1], ["Closed", 1], ["Paper", 1], ["Backtest", 1], ["z", 1], ["Status"]], fwdRows, "md-lt md-fw")}</div><div class="only-m md-vl">${fwdCards}</div>
    <div class="note">${AU ? `Each session counts once: the average of the trades that opened that day, after costs, as in the backtest. z is how far the paper average sits from the 2025–26 backtest, in standard errors of an average over that many sessions. A book passes at ${NEED} sessions with a positive average and z above −1; z between −2 and −1, or a loss, is a warning; z of −2 or less fails it, and so does −2.5 or less after only 20 sessions. The cone is the backtest's own 1st and 5th percentile for that many sessions. Your slippage comes from “I placed it” on the Live tab: up to 0.05% is fine, over 0.10% fails.` : `A book passes only after ${NEED} sessions with trades, a positive average after costs, and an average within one standard error of its backtest. Two standard errors below the backtest, or a loss, fails it.`} Passing is the minimum before a small live size is considered; it does not make the backtest numbers likely. Intraday longs are not approved and are only followed.</div>${hyp}
    ${h("Trades", `${j.rows.length} · ${j.open} open · results after costs`)}${tbl([["Day"], ["Stock"], ["Result", 1], ["State"], ["Entry", 1], ["Stop", 1], ["Target", 1], ["Exit / last", 1], ...(isDesk() ? [["Your fill", 1]] : [])], rows, "md-lt")}
    <div class="note">Swing trades open at the first session's opening price. ${KEEP(d) ? `Longs opened from 28 Nov 2026 follow the keep rule: the stop${KT(d) ? `, the target (${KT(d)} ATR, from 30 Nov 2026)` : ""}, then sold at the next open once the model ranks the stock outside its top ${KEEP(d).keep_rank}, at most ${KEEP(d).max_hold} sessions. Shorts follow the stop, target and ${d.rules.hold}-session rule. Stops and targets are on the exchange's tick grid, as in the 9:16 alert.` : `They follow the model's stop, target and ${d.rules.hold}-session rule.`} Intraday shorts are bought back at about 3:05 pm, before the broker's 3:10 pm square-off. They are logged a few minutes after the open with two prices: the official open and the price the market showed then. The gap between the two results is the real cost of not selling in the opening auction. Intraday longs are opened only when a stock opens at or under its buy limit (at most ${d.day_long ? d.day_long.rules.max : 10} a day), with the stop ${d.day_long ? d.day_long.rules.stop_atr : 1} ATR under the fill${d.day_long && d.day_long.rules.target_atr ? ` and the target ${d.day_long.rules.target_atr} ATR over it` : ""}, and sold by 3:05 pm. Intraday shorts carry their stop${d.day && d.day.rules.target_atr ? ` and target (${d.day.rules.stop_atr} and ${d.day.rules.target_atr} ATR)` : ""} from the official open.</div>`;
}
// ── Lab: intraday ideas tested on five-minute candles ──
function loadLab() { const M = S.md; if (M.lbusy || M.lab !== undefined) return; M.lbusy = true; api("/api/desk?f=ilab").then((x) => { M.lab = x && x.tests ? x : null; }).catch(() => { M.lab = null; }).finally(() => { M.lbusy = false; paint(); }); }
function lab() {
  const M = S.md; loadLab(); if (M.lab === undefined) return `<div class="card"><div class="note">Reading the lab results…</div></div>`;
  const L = M.lab; if (!L) return `<div class="md-ban a"><span class="chip a">No results yet</span><div><b>The intraday lab has not run.</b><small>Run "Intraday data" in GitHub Actions (first time with 730 days). It collects five-minute candles and then tests the ideas below on them.</small></div></div>
    <div class="card pad md-reg"><b>What it will test</b><ul><li>The intraday book on real five-minute prices: sold at 9:15, 9:20, 9:30 and 10:00.</li><li>Opening range breakout on the ten stocks with the highest opening volume (5, 15 and 30 minutes).</li><li>Whether the move to 9:45 predicts the last half hour, for NIFTY, BANK NIFTY and stocks.</li><li>Whether the day's biggest losers rebound in the last half hour.</li></ul></div>`;
  const vc = { holds: "g", fails: "r", unclear: "a" }, groups = [...new Set(L.tests.map((t) => t.group))];
  const lcard = (t) => `<div><span><b>${esc(t.name)}</b><small><i class="${col(t.mean)}">${sg(t.mean, 3)} a day</i> · t ${ok(t.t) ? num(t.t, 1) : "—"} · first part ${t.first ? sg(t.first.mean, 3) : "—"} · later ${t.later ? sg(t.later.mean, 3) : "—"} · worst fall ${ok(t.maxdd) ? num(t.maxdd, 1) + "%" : "—"}</small><small>${esc(t.why || "")}${t.note ? `${t.why ? " · " : ""}${esc(t.note)}` : ""}</small></span><span class="chip ${vc[t.verdict] || ""}">${esc(t.verdict)}</span></div>`;
  const body = groups.map((g) => h(g.replace(/^Day book/, "Intraday book")) + `<div class="md-qn md-vl">${L.tests.filter((t) => t.group === g).map(lcard).join("")}</div><div class="md-qw">` + tbl([["Rule"], ["Verdict"], ["A day", 1], ["t", 1], ["First 60%", 1], ["Later 40%", 1], ["Winning days", 1], ["Worst fall", 1]], L.tests.filter((t) => t.group === g).map((t) => `<tr><td>${esc(t.name)}<small>cost ${num(t.cost, 2)}% a round trip${t.trades ? ` · ${num(t.trades, 0)} trades` : ""}${t.note ? " · " + esc(t.note) : ""}</small></td><td><span class="chip ${vc[t.verdict] || ""}">${esc(t.verdict)}</span><small>${esc(t.why || "")}</small></td><td class="r ${col(t.mean)}">${sg(t.mean, 3)}</td><td class="r">${ok(t.t) ? num(t.t, 1) : "—"}</td><td class="r ${col(t.first && t.first.mean)}">${t.first ? sg(t.first.mean, 3) : "—"}</td><td class="r ${col(t.later && t.later.mean)}">${t.later ? sg(t.later.mean, 3) : "—"}</td><td class="r">${ok(t.won) ? num(t.won, 0) + "%" : "—"}</td><td class="r dn">${ok(t.maxdd) ? num(t.maxdd, 1) + "%" : "—"}</td></tr>`), "md-lt md-lab") + "</div>").join("");
  const path = L.day_path ? h("When the intraday picks fall", `average of ${L.day_path.days} days, from the 9:15 price, before costs`) + `<div class="card pad">${lineChart(L.day_path.t, [{ n: "Ten best short ranks", c: AMBER, v: L.day_path.pct, w: 2 }, ...(L.all_path ? [{ n: "All F&O stocks", c: T3, v: L.all_path, w: 1.4 }] : [])], { h: 240, fmt: (v) => num(v, 2) + "%" })}${legend([["Ten best short ranks", AMBER], ["All F&O stocks", T3]])}<div class="note">${esc(L.day_path.note)}</div></div>` : "";
  return `<div class="md-lh"><div><b>Intraday lab</b><small>${num(L.data.days, 0)} sessions of five-minute candles, ${nice(L.data.first)} to ${nice(L.data.last)}, ${L.data.symbols} symbols. ${esc(L.rule)}</small></div><div><small>Run</small><b>${nice(String(L.built).slice(0, 10))}</b></div></div>${path}<div class="md-cq">${body}</div>
    <div class="note">The list of ideas was fixed before any five-minute data was seen. A rule added afterwards says so in its verdict and stays "unclear" until enough new days have passed. A rule that fails here is not shown as a signal anywhere on the site. Rules marked "the rule now" are the ones the alerts follow.</div>${L.data_checks ? `<div class="note"><b>Checks on the five-minute feed:</b> ${num(L.data_checks.no_open_bar, 2)}% of ${num(L.data_checks.stock_days, 0)} stock-days have no 9:15 bar, ${num(L.data_checks.short_days, 2)}% have fewer than 60 of 75 bars, ${num(L.data_checks.jumps, 0)} one-bar jumps of 10% or more, ${num(L.data_checks.bad_bars, 0)} impossible bars. A sudden rise in these means the feed changed, not the market.</div>` : ""}`;
}
function strip(d) {                                         // one line of market state above every model tab
  const m = d.market, chip = (l, s2) => { const q = Q(s2); return `<span class="md-sc"><small>${l}</small><b>${q ? px(q.price) : "—"}</b><i class="${col(q && q.pct)}">${q ? sg(q.pct, 2) : ""}</i></span>`; };
  return `<div class="md-strip"><span class="md-sc ${REG_C[m.regime] || ""}"><small>Regime</small><b>${esc(m.regime)}</b></span>${chip("NIFTY 50", "^NSEI")}${chip("BANK NIFTY", "^NSEBANK")}${chip("India VIX", "^INDIAVIX")}${d.nifty ? `<span class="md-sc ${NC_C[d.nifty.call] || ""}"><small>NIFTY call</small><b>${esc(NC_W[d.nifty.call].replace(" · stand aside", ""))}</b></span>` : ""}<span class="md-sc"><small>Swing trades</small><b>${esc(d.decision === "NO TRADE" ? "None new" : d.decision.replace("BUY", "buy").replace("SHORT", "short"))}</b></span>${d.day ? `<span class="md-sc"><small>Intraday trades</small><b>${d.day.picks.length} short${d.day.size < 1 ? " · half" : ""}</b></span>` : ""}<span class="md-sc"><small>Model run</small><b>${nice(d.asof).replace(/ \d{4}$/, "")}</b></span>${S.live ? '<span class="md-sc g"><small>Prices</small><b>Live</b></span>' : ""}</div>`;
}
export function view(tab) {
  const M = S.md, d = M.d;
  if (d === undefined) { load(); return `<div class="card"><div class="note">Loading the model…</div></div>`; }
  if (!d) return M.err ? `<div class="card"><div class="empty"><b>The model file could not be read</b>${esc(M.err)}</div></div>` : setup;
  RES = Object.fromEntries((d.universe || []).filter((u) => u.res).map((u) => [u.sym, u.res]));
  try { return `<div class="md">${strip(d)}${tab === "Plan" ? plan(d) : tab === "Live" ? live(d) : tab === "Day book" ? daybook(d) : tab === "Journal" ? journal(d) : tab === "Lab" ? lab() : tab === "Charts" ? charts(d) : tab === "Track record" ? record(d) : tab === "Validation" ? sims(d) : tab === "Method" ? method(d) : tonight(d)}<div class="note">Model output from end-of-day data. It can and does lose money. Not investment advice.</div></div>`; }
  catch (er) { return `<div class="card"><div class="empty"><b>This view could not be drawn</b>${esc(er.name)}: ${esc(String(er.message).slice(0, 200))}</div></div>`; }
}
export function input(el, ev) {
  const M = S.md, k = el.dataset.md; if (ev !== "change") return;
  if (k === "cap") { M.cap = Math.max(0, +el.value || 0); try { localStorage.setItem("arka_model_cap", String(M.cap)); } catch { /* private mode */ } }
  if (k && /^(set|tg|books):/.test(k)) { const [g, f] = k.split(":"), base = (M.set && M.set.settings) || {}; M.sf = M.sf || {}; M.smsg = "";
    if (g === "set") M.sf[f] = el.value === "" ? 0 : +el.value; else M.sf[g] = { ...(base[g] || {}), ...(M.sf[g] || {}), [f]: el.checked }; }
  if (k === "sym") M.sym = el.value;
  if (el.type !== "checkbox" && el.tagName === "INPUT" && document.activeElement === el) el.addEventListener("blur", () => paint(), { once: true });      // Enter in a box: redraw when you leave it, not under the cursor
  else paint();
}
export function act(name, el) {
  const M = S.md, v = el.dataset.v;
  if (name === "mdlist") { M.list = v; return paint(); }
  if (name === "mdper") { M.per = v; return paint(); }
  if (name === "mdside") { M.side = v; return paint(); }
  if (name === "mdlive") { M.lid = v; M.lsym = v.split(":").pop(); paint(); if (window.innerWidth < 1200) requestAnimationFrame(() => { const el = document.getElementById("md-det"); if (el) el.scrollIntoView({ block: "center", behavior: "smooth" }); }); return; }
  if (name === "mdlsort") { M.lsort = v; return paint(); }
  if (name === "mdlall") { M.lall = !M.lall; return paint(); }
  if (name === "mdchart") { M.sym = v; S.fd.tab = "Charts"; window.scrollTo(0, 0); return paint(); }
  if (name === "mdsetsave") { if (!M.set || !M.set.settings || M.ssave) return; M.ssave = true; M.smsg = ""; paint();
    api("/api/settings", { method: "POST", body: JSON.stringify({ ...M.set.settings, ...(M.sf || {}) }) }).then((x) => { M.set = { ...M.set, settings: x.settings, telegram: x.telegram }; M.sf = {}; M.smsg = "Saved. The 8:45 alert uses these."; })
      .catch((e) => { M.smsg = e.message || "Could not save."; }).finally(() => { M.ssave = false; paint(); }); return; }
}
